# Golden Gate assembly, generated by the DELPHI kernel. NOT RUN ON HARDWARE.
# Review every volume and every deck position before you put this on a robot.
# Construct: and2. Slots with a sequence from a primary record: 3 of 14.
# Open slots are NOT in this protocol; they cannot be pipetted until a sequence exists for them.
from opentrons import protocol_api

metadata = {"protocolName": "DELPHI Golden Gate: and2", "author": "DELPHI kernel", "apiLevel": "2.19"}

def run(protocol: protocol_api.ProtocolContext):
    tips = protocol.load_labware("opentrons_96_filtertiprack_20ul", 1)
    parts_plate = protocol.load_labware("biorad_96_wellplate_200ul_pcr", 2)
    rxn_plate = protocol.load_labware("biorad_96_wellplate_200ul_pcr", 3)
    reagents = protocol.load_labware("opentrons_24_tuberack_nest_1.5ml_snapcap", 4)
    p20 = protocol.load_instrument("p20_single_gen2", "right", tip_racks=[tips])
    tc = protocol.load_module("thermocyclerModuleV2")

    mix = reagents.wells_by_name()["A1"]   # T4 ligase buffer + BsaI-HFv2 + T4 DNA ligase
    water = reagents.wells_by_name()["A2"]
    rxn = rxn_plate.wells_by_name()["A1"]

    p20.transfer(2.0, mix, rxn, new_tip="always")
    p20.transfer(1.0, parts_plate.wells_by_name()["A1"], rxn, new_tip="always")   # BBa_B0034 (rbs, 22 bp)
    p20.transfer(1.0, parts_plate.wells_by_name()["B1"], rxn, new_tip="always")   # BBa_B0034 (rbs, 22 bp)
    p20.transfer(1.0, parts_plate.wells_by_name()["C1"], rxn, new_tip="always")   # BBa_B0034 (rbs, 22 bp)
    p20.transfer(15.0, water, rxn, new_tip="always")

    tc.close_lid()
    tc.set_lid_temperature(105)
    tc.execute_profile(steps=[{"temperature": 37, "hold_time_minutes": 5},
                              {"temperature": 16, "hold_time_minutes": 5}], repetitions=30, block_max_volume=20)
    tc.set_block_temperature(60, hold_time_minutes=5)
    tc.set_block_temperature(10)
    tc.open_lid()
    protocol.comment("Transform 2 uL into chemically competent E. coli Escherichia coli by hand.")
